INSERT INTO "pages" ("id", "nav_id", "datetime", "title", "description", "logo", "content", "content_json", "is_active", "is_delete", "created_at", "updated_at", "rss_yandex_id", "is_template", "template_id", "css") VALUES (7, 1, '2026-09-21 23:52:22.518798', 'Базовый шаблон', '', '', '<style>* { box-sizing: border-box; } body {margin: 0;}*{box-sizing:border-box;}body{margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px;}</style><body id="i6bz"><div class="flex-shell"><nav class="flex-shell__nav">Nav</nav><main class="flex-shell__main"><aside class="flex-shell__area flex-shell__area--left"></aside><section class="flex-shell__area flex-shell__area--center">
             </section><aside class="flex-shell__area flex-shell__area--right"></aside></main><footer class="flex-shell__footer">Footer</footer></div></body>', '{"assets":[{"type":"image","src":"/media/default/logo_ec0d8ede.png","unitDim":"px","height":0,"width":0,"name":"logo_ec0d8ede.png"}],"styles":[{"selectors":[],"selectorsAdd":"*","style":{"box-sizing":"border-box"}},{"selectors":[],"selectorsAdd":"body","style":{"margin-top":"0px","margin-right":"0px","margin-bottom":"0px","margin-left":"0px"}}],"pages":[{"frames":[{"component":{"type":"wrapper","stylable":["background","background-color","background-image","background-repeat","background-attachment","background-position","background-size"],"attributes":{"id":"i6bz"},"components":[{"classes":["flex-shell"],"components":[{"tagName":"nav","type":"text","classes":["flex-shell__nav"],"components":[{"type":"textnode","content":"Nav"}]},{"tagName":"main","classes":["flex-shell__main"],"components":[{"tagName":"aside","classes":["flex-shell__area","flex-shell__area--left"]},{"tagName":"section","type":"text","classes":["flex-shell__area","flex-shell__area--center"],"components":[{"type":"textnode","content":"\n             "}]},{"tagName":"aside","classes":["flex-shell__area","flex-shell__area--right"]}]},{"tagName":"footer","type":"text","classes":["flex-shell__footer"],"components":[{"type":"textnode","content":"Footer"}]}]}],"head":{"type":"head"},"docEl":{"tagName":"html"}},"id":"FHHmqPJVirvBsKDK"}],"type":"main","id":"B4OjPqKrfsQXpWBA"}],"symbols":[]}', 1, 1, '2026-09-21 23:52:22.518838', '2026-09-24 09:49:30.978270', NULL, 1, NULL, NULL);
INSERT INTO "pages" ("id", "nav_id", "datetime", "title", "description", "logo", "content", "content_json", "is_active", "is_delete", "created_at", "updated_at", "rss_yandex_id", "is_template", "template_id", "css") VALUES (8, 1, '2026-09-22 17:58:41.785457', 'Шаблон со слотом', '', '', '<body><p></p><div class="flex-shell"><nav class="flex-shell__nav">Nav</nav><main class="flex-shell__main"><aside class="flex-shell__area flex-shell__area--left"></aside><section class="flex-shell__area flex-shell__area--center"><div data-slot="content"><h2>Сингулярность: граница известного</h2><p>Сингулярность — одно из тех понятий, которое одинаково охотно используют физики, математики и авторы научной фантастики. В самом общем смысле речь идёт о точке, в которой привычные законы перестают работать, а величины, описывающие систему, устремляются к бесконечности или теряют определённость. Именно поэтому сингулярность одновременно притягивает исследователей и ставит перед ними принципиальный вопрос: где заканчивается область, о которой мы можем рассуждать строго, и начинается территория догадок.</p><h3>Гравитационная сингулярность</h3><p>В общей теории относительности гравитационная сингулярность возникает как решение уравнений поля, при котором кривизна пространства-времени неограниченно возрастает. Классический пример — центр чёрной дыры: согласно теории, вещество, попавшее под горизонт событий, уже не может вернуться, а его плотность в пределе стремится к бесконечно большому значению. Для внешнего наблюдателя такая область выглядит почти пустой: свет не выходит наружу, и увидеть сингулярность напрямую невозможно. Мы можем судить о ней лишь по косвенным признакам — по движению соседних звёзд, по рентгеновскому излучению аккреционных дисков, по гравитационным волнам, возникающим при слиянии массивных объектов.</p><p>Отдельного внимания заслуживает горизонт событий — не физическая поверхность, а граница причинности. Пересекая её, наблюдатель не замечает резкой перемены, однако его дальнейшая судьба предопределена: любая траектория ведёт к центру. Этот парадокс долгое время служил поводом для споров о том, является ли сингулярность реальным объектом природы или же свидетельством того, что теория относительности применима лишь до определённого предела.</p><h3>Космологическая сингулярность</h3><p>Другая известная форма — космологическая сингулярность, с которой связывают начало расширения Вселенной. Если мысленно обратить ход времени вспять, галактики, звёзды и газ будут сближаться, а плотность и температура — расти. Экстраполяция приводит к состоянию, где расстояния между объектами стремятся к нулю. Однако важно понимать: это математический предел модели, а не обязательно описание того, что происходило в действительности. Современная космология рассматривает раннюю Вселённую через призму инфляции и квантовых процессов, и на планковских масштабах привычные уравнения требуют уточнения.</p><h3>Технологическая сингулярность</h3><p>Термин используют и за пределами физики. Технологической сингулярностью называют гипотетический момент, когда развитие искусственного интеллекта и вычислительных систем станет настолько быстрым и сложным, что дальнейшие изменения невозможно достоверно прогнозировать. Сторонники этой идеи указывают на экспоненциальный рост вычислительных мощностей и объёмов данных; критики напоминают, что любой прогноз опирается на допущения, а значит, остаётся сценарием, а не расписанием. Тем не менее сама постановка вопроса полезна: она заставляет заранее обсуждать управляемость, безопасность и границы ответственности.</p><h3>Почему это важно</h3><p>Сингулярность интересна не только как эффектный образ. Она обозначает рубеж применимости наших моделей и подсказывает, где нужны новые теории. Каждый раз, когда расчёты приводят к бесконечности, это сигнал: описание неполно. Так было с классической механикой, так происходит и сейчас с квантовой гравитацией. Поиск корректной теории вблизи сингулярности — одна из центральных задач современной физики, и её решение способно изменить наши представления о пространстве, времени и причинности.</p><p>Пока же сингулярность остаётся точкой встречи строгой науки и воображения. Она напоминает о том, что у знания есть границы, и что именно на этих границах рождаются самые продуктивные вопросы.</p></div></section><aside class="flex-shell__area flex-shell__area--right"></aside></main><footer class="flex-shell__footer">Footer</footer></div></body>', '{"assets":[{"type":"image","src":"/media/default/logo_ec0d8ede.png","unitDim":"px","height":0,"width":0,"name":"logo_ec0d8ede.png"}],"styles":[],"pages":[{"frames":[{"component":{"type":"wrapper","stylable":["background","background-color","background-image","background-repeat","background-attachment","background-position","background-size"],"components":[{"tagName":"p"},{"classes":["flex-shell"],"components":[{"tagName":"nav","type":"text","droppable":true,"classes":["flex-shell__nav"],"components":[{"type":"textnode","content":"Nav"}]},{"tagName":"main","classes":["flex-shell__main"],"components":[{"tagName":"aside","draggable":".flex-shell__main","classes":["flex-shell__area","flex-shell__area--left"]},{"tagName":"section","classes":["flex-shell__area","flex-shell__area--center"],"components":[{"attributes":{"data-slot":"content"},"components":[{"tagName":"h2","type":"text","components":[{"type":"textnode","content":"Сингулярность: граница известного"}]},{"tagName":"p","type":"text","components":[{"type":"textnode","content":"Сингулярность — одно из тех понятий, которое одинаково охотно используют физики, математики и авторы научной фантастики. В самом общем смысле речь идёт о точке, в которой привычные законы перестают работать, а величины, описывающие систему, устремляются к бесконечности или теряют определённость. Именно поэтому сингулярность одновременно притягивает исследователей и ставит перед ними принципиальный вопрос: где заканчивается область, о которой мы можем рассуждать строго, и начинается территория догадок."}]},{"tagName":"h3","type":"text","components":[{"type":"textnode","content":"Гравитационная сингулярность"}]},{"tagName":"p","type":"text","components":[{"type":"textnode","content":"В общей теории относительности гравитационная сингулярность возникает как решение уравнений поля, при котором кривизна пространства-времени неограниченно возрастает. Классический пример — центр чёрной дыры: согласно теории, вещество, попавшее под горизонт событий, уже не может вернуться, а его плотность в пределе стремится к бесконечно большому значению. Для внешнего наблюдателя такая область выглядит почти пустой: свет не выходит наружу, и увидеть сингулярность напрямую невозможно. Мы можем судить о ней лишь по косвенным признакам — по движению соседних звёзд, по рентгеновскому излучению аккреционных дисков, по гравитационным волнам, возникающим при слиянии массивных объектов."}]},{"tagName":"p","type":"text","components":[{"type":"textnode","content":"Отдельного внимания заслуживает горизонт событий — не физическая поверхность, а граница причинности. Пересекая её, наблюдатель не замечает резкой перемены, однако его дальнейшая судьба предопределена: любая траектория ведёт к центру. Этот парадокс долгое время служил поводом для споров о том, является ли сингулярность реальным объектом природы или же свидетельством того, что теория относительности применима лишь до определённого предела."}]},{"tagName":"h3","type":"text","components":[{"type":"textnode","content":"Космологическая сингулярность"}]},{"tagName":"p","type":"text","components":[{"type":"textnode","content":"Другая известная форма — космологическая сингулярность, с которой связывают начало расширения Вселенной. Если мысленно обратить ход времени вспять, галактики, звёзды и газ будут сближаться, а плотность и температура — расти. Экстраполяция приводит к состоянию, где расстояния между объектами стремятся к нулю. Однако важно понимать: это математический предел модели, а не обязательно описание того, что происходило в действит