al, normal;transition-duration:0.6s, 0.6s;transition-timing-function:cubic-bezier(0.22, 0.9, 0.3, 1), ease;transition-delay:0s, 0s;transition-property:transform, box-shadow;}.effect-r8n5 .text-image__media:hover .image{transform:scale(1.02);box-shadow:rgba(0, 0, 0, 0.6) 0px 40px 70px -34px;}.effect-p5d1 .steps__item{position:relative;transition-behavior:normal;transition-duration:0.35s;transition-timing-function:ease;transition-delay:0s;transition-property:transform;}.effect-p5d1 .steps__item:hover{transform:translateY(-4px);}.effect-p5d1 .steps__num{position:relative;border-top-left-radius:999px;border-top-right-radius:999px;border-bottom-right-radius:999px;border-bottom-left-radius:999px;background-image:linear-gradient(140deg, var(--theme-primary, #c9a06a), var(--theme-accent, #6fae9a));color:var(--theme-on-primary, #fff);box-shadow:rgba(0, 0, 0, 0.55) 0px 12px 28px -14px;transition-behavior:normal;transition-duration:0.35s;transition-timing-function:ease;transition-delay:0s;transition-property:transform;}.effect-p5d1 .steps__item:hover .steps__num{transform:scale(1.08);}.effect-p5d1 .steps__num::after{content:"";position:absolute;top:0px;right:0px;bottom:0px;left:0px;border-top-left-radius:inherit;border-top-right-radius:inherit;border-bottom-right-radius:inherit;border-bottom-left-radius:inherit;pointer-events:none;animation-duration:2.8s;animation-timing-function:ease-out;animation-delay:0s;animation-iteration-count:infinite;animation-direction:normal;animation-fill-mode:none;animation-play-state:running;animation-name:effect-p5d1-ring;animation-timeline:auto;animation-range-start:normal;animation-range-end:normal;}.effect-p5d1 .steps__item:nth-child(2) .steps__num::after{animation-delay:0.9s;}.effect-p5d1 .steps__item:nth-child(3) .steps__num::after{animation-delay:1.8s;}.effect-x8c4 .gallery__item{border-top-left-radius:16px;border-top-right-radius:16px;border-bottom-right-radius:16px;border-bottom-left-radius:16px;animation-duration:0.9s;animation-timing-function:ease;animation-delay:0s;animation-iteration-count:1;animation-direction:normal;animation-fill-mode:both;animation-play-state:running;animation-name:effect-x8c4-in;animation-timeline:auto;animation-range-start:normal;animation-range-end:normal;transition-behavior:normal, normal, normal;transition-duration:0.5s, 0.5s, 0.5s;transition-timing-function:cubic-bezier(0.22, 0.9, 0.3, 1), ease, ease;transition-delay:0s, 0s, 0s;transition-property:transform, filter, box-shadow;}.effect-x8c4 .gallery__item:nth-child(2){animation-delay:0.08s;}.effect-x8c4 .gallery__item:nth-child(3){animation-delay:0.16s;}.effect-x8c4 .gallery__item:nth-child(4){animation-delay:0.24s;}.effect-x8c4 .gallery__item:nth-child(5){animation-delay:0.32s;}.effect-x8c4 .gallery__item:nth-child(6){animation-delay:0.4s;}.effect-x8c4 .gallery__item:hover{transform:translateY(-6px) scale(1.03);filter:saturate(118%) contrast(104%);box-shadow:rgba(0, 0, 0, 0.6) 0px 28px 52px -26px;}.effect-w2f6{position:relative;overflow-x:hidden;overflow-y:hidden;isolation:isolate;}.effect-w2f6::before{content:"";position:absolute;top:0px;right:0px;bottom:0px;left:0px;z-index:-1;pointer-events:none;background-size:220% 100%;opacity:0.18;animation-duration:16s;animation-timing-function:ease-in-out;animation-delay:0s;animation-iteration-count:infinite;animation-direction:alternate;animation-fill-mode:none;animation-play-state:running;animation-name:effect-w2f6-shift;animation-timeline:auto;animation-range-start:normal;animation-range-end:normal;}.effect-w2f6 .cta__btn{position:relative;animation-duration:3.2s;animation-timing-function:ease-out;animation-delay:0s;animation-iteration-count:infinite;animation-direction:normal;animation-fill-mode:none;animation-play-state:running;animation-name:effect-w2f6-pulse;animation-timeline:auto;animation-range-start:normal;animation-range-end:normal;transition-behavior:normal;transition-duration:0.3s;transition-timing-function:ease;transition-delay:0s;transition-property:transform;}.effect-w2f6 .cta__btn:hover{transform:translateY(-3px);}.effect-sbg1{background-image:repeating-linear-gradient(115deg,
      color-mix(in srgb, var(--theme-primary, #2f6f5e) 6%, transparent) 0 1px,
      transparent 1px 38px),
